// Extraire les données de Google Vision
const visionResponse = items[0].json.responses[0];

// Texte complet (OCR)
const extractedText = visionResponse.textAnnotations[0].description;

// Extraire le titre (première ligne du texte)
const firstLine = extractedText.split('\n')[0];

// Nettoyer pour créer un nom de fichier valide
// Enlever les caractères spéciaux, garder juste lettres, chiffres, espaces et tirets
const cleanFileName = firstLine
  .replace(/[^a-zA-Z0-9\sàâäéèêëïîôùûüç\-]/g, '') // Garde lettres FR + chiffres + espaces + tirets
  .trim()
  .substring(0, 50); // Limite à 50 caractères

return [{
  json: {
    extractedText: extractedText,
    courseTitle: cleanFileName, // Nom de fichier propre
    keywords: firstLine // Le titre brut comme mot-clé
  }
}];

// Parser la réponse JSON de Gemini
const geminiResponse = items[0].json;

// Extraire le texte de la réponse Gemini
let responseText = geminiResponse.content?.parts?.[0]?.text || geminiResponse.text || "";

// Parser le JSON (Gemini peut renvoyer du texte avec ```json, on nettoie)
responseText = responseText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

const parsed = JSON.parse(responseText);

return [{
  json: {
    title: parsed.title,
    correctedText: parsed.correctedText
  }
}];

